"     const outletIdToPass = biz.user_id || biz.parent_user_id || biz.id;

     // Fetch Table Departments
     try {
       const deptRes = await posService.getTableDepartments(outletIdToPass);
       setTableDepartments(deptRes.data || []);
       localStorage.setItem('pos_table_departments', JSON.stringify(deptRes.data || []));
     } catch (e) {
       console.warn("initApp - Failed to load table departments:", e);
     }

     // Fetch Table Customers
     try {
       const tableCustomersRes = await posService.getTableCustomers(outletIdToPass);
       setTableCustomers(tableCustomersRes.data || []);
       localStorage.setItem('pos_table_customers', JSON.stringify(tableCustomersRes.data || []));
     } catch (e) {
       console.warn("initApp - Failed to load table customers:", e);
     }

